import React, { useEffect, useState } from "react";
import { User, Mail, Edit, LogOut, Award, ChevronDown } from "lucide-react";
import { useNavigate } from "react-router-dom";
import "../App.css"; 

export default function Profile() {
  const navigate = useNavigate();

  // 1. Set default state (Using "Srija" only as a placeholder if no one is logged in)
  const [user, setUser] = useState({
    name: "Srija",
    email: "srija@gmail.com",
    grade: "Grade 10"
  });

  // 2. When page loads, get the REAL name from memory
  useEffect(() => {
    const storedName = localStorage.getItem("userName");
    const storedEmail = localStorage.getItem("userEmail");

    if (storedName) {
      setUser(prev => ({ ...prev, name: storedName }));
    }
    if (storedEmail) {
      setUser(prev => ({ ...prev, email: storedEmail }));
    }
  }, []);

  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
    window.location.reload(); 
  };

  return (
    <div className="profile-page-container" style={{ padding: '2rem', maxWidth: '1000px', margin: '0 auto' }}>

      {/* HEADER CARD - EXACT SAME UI AS YOUR PICTURE */}
      <div className="profile-header-card" style={{ 
          background: 'linear-gradient(135deg, #0d9488 0%, #115e59 100%)', // The Teal Gradient
          borderRadius: '16px', 
          padding: '2rem', 
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1)'
      }}>

        <div style={{ display: 'flex', alignItems: 'center', gap: '1.5rem' }}>
            {/* White Box for Icon */}
            <div style={{ background: 'white', padding: '12px', borderRadius: '12px', display: 'flex', alignItems:'center', justifyContent:'center', height:'60px', width:'60px' }}>
                <User size={32} color="#0d9488" />
            </div>

            <div>
                {/* 3. DYNAMIC NAME HERE */}
                <h1 style={{ margin: 0, fontSize: '2rem', fontWeight: 'bold' }}>{user.name}</h1>
                <p style={{ margin: '5px 0 0 0', opacity: 0.9, display: 'flex', alignItems: 'center', gap: '8px', fontSize:'0.9rem' }}>
                    {user.grade} • <Mail size={14} /> {user.email}
                </p>
            </div>
        </div>

        <div style={{ display: 'flex', gap: '10px' }}>
            <button style={{
                background: 'white', color: '#0f172a', border: 'none', padding: '8px 16px', borderRadius: '8px', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer'
            }}>
                <Edit size={16} /> Edit Profile
            </button>
            <button onClick={handleLogout} style={{
                background: 'rgba(255,255,255,0.2)', color: 'white', border: '1px solid rgba(255,255,255,0.3)', padding: '8px 16px', borderRadius: '8px', fontWeight: 'bold', display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer'
            }}>
                <LogOut size={16} /> Sign Out
            </button>
        </div>
      </div>

      {/* LEVEL PROGRESS SECTION - KEEPING YOUR UI */}
      <div style={{ marginTop: '2rem', background: 'white', padding: '1.5rem', borderRadius: '16px', border: '1px solid #e2e8f0' }}>
         <h3 style={{margin: '0 0 1rem 0', color: '#0f172a', display:'flex', alignItems:'center', gap:'8px'}}>
             <Award size={20} color="#0d9488"/> Level Progress
         </h3>

         <div style={{background: '#f1f5f9', padding: '1rem', borderRadius: '12px', display: 'flex', alignItems: 'center', gap: '1rem'}}>
             <div style={{background: '#0d9488', color: 'white', width: '40px', height: '40px', borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold'}}>
                 1
             </div>
             <div style={{flex: 1}}>
                 <div style={{display:'flex', justifyContent:'space-between', marginBottom:'5px', fontSize:'0.9rem', fontWeight:'bold', color:'#334155'}}>
                     <span>Level 1402 / 500 XP</span>
                 </div>
                 <div style={{width:'100%', height:'8px', background:'#cbd5e1', borderRadius:'4px'}}>
                     <div style={{width:'20%', height:'100%', background:'#0d9488', borderRadius:'4px'}}></div>
                 </div>
                 <div style={{fontSize:'0.8rem', color:'#64748b', marginTop:'4px'}}>98 XP until Level 2</div>
             </div>
         </div>
      </div>

      {/* BADGES SECTION */}
      <div style={{ marginTop: '2rem', background: 'white', padding: '1.5rem', borderRadius: '16px', border: '1px solid #e2e8f0', minHeight: '200px' }}>
         <h3 style={{margin: '0 0 1rem 0', color: '#0f172a'}}>Badges</h3>
         <div style={{textAlign: 'center', color: '#94a3b8', marginTop: '2rem'}}>
             <Award size={40} style={{opacity: 0.3}} />
             <p>Complete quizzes to earn badges!</p>
         </div>
      </div>

    </div>
  );
}
